function npvAt(rate, init, arr){ var v=-init; for(var t=1;t<=arr.length;t++){ v+=arr[t-1]/Math.pow(1+rate,t);} return v; }
function irr(init, flows){
  init=(+init); if(isNaN(init)) init=0;
  var arr=String(flows||'').trim().split(/[\s,;]+/).filter(function(x){return x.length;}).map(function(x){var v=+x; return isNaN(v)?0:v;});
  if(!arr.length) return {error:'请至少输入一期现金流'};
  var lo=-0.99, hi=10, fLo=npvAt(lo,init,arr), fHi=npvAt(hi,init,arr);
  if(fLo*fHi>0) return {error:'在 -99%~1000% 区间无变号，无法用二分法求 IRR'};
  for(var i=0;i<200;i++){ var mid=(lo+hi)/2; var fM=npvAt(mid,init,arr); if(Math.abs(fM)<1e-7) break; if(fLo*fM<0){hi=mid;fHi=fM;} else {lo=mid;fLo=fM;} }
  var res=(lo+hi)/2;
  return {irr:Math.round(res*10000)/10000, pct:Math.round(res*10000)/100};
}
var EXPORTS={irr:irr};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.IrrForgePure = EXPORTS; }
